Personally I've looked at the 6 time_id nearest neighbors, calculated their starting and ending prices, and brute-forced all 6! permutations to find the shortest Hamiltonian path, which is the most likely ordering of those 6 time_ids
indices = [0, 1, 2, 3, 4, 5] # some list of time ids that are close to each other
def vec_distance(vec1, vec2):
    return np.sqrt(np.sum((vec1 - vec2)**2))
def get_total_distance(seq):
    return sum([vec_distance(np_start[i], np_end[j]) for i,j in zip(seq[1:], seq[:-1])])
indices = np.array([list(list(permutations(a))[np.argmin(list(map(get_total_distance, permutations(a))))]) for a in indices])

